INSERT INTO feature VALUES('forall-types','checking','The quantifier type forall a . T','implicit-arguments','declined','ordinary',NULL,'Declined by #1055: implicitness is a property of a declaration, never of its type, so there is no implicit Pi. A function quantifies over types in its prefix block, `[a : Type]`, which the checker supplies at each call; the `forall_type` rule is deleted.',NULL,NULL,NULL,'#1055');
